//! rust-hashcat — брутфорсер хешей в стиле hashcat.
//!
//! Запуск: `rust_hashcat --hash <HEX> -m <ТИП> -a <РЕЖИМ> [опции]`
//! Полная справка: `rust_hashcat --help`

mod attack;
mod charset;
mod cli;
mod engine;
mod gpu;
mod hash;
mod potfile;

use std::process::ExitCode;

const VERSION: &str = env!("CARGO_PKG_VERSION");

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();

    let cfg = match cli::parse_args(&args) {
        Ok(cli::ParseResult::Help) => {
            println!("{}", cli::HELP);
            return ExitCode::SUCCESS;
        }
        Ok(cli::ParseResult::Version) => {
            println!("rust-hashcat {}", VERSION);
            return ExitCode::SUCCESS;
        }
        Ok(cli::ParseResult::Run(cfg)) => cfg,
        Err(e) => {
            eprintln!("ошибка: {}", e);
            eprintln!("используйте --help для справки");
            return ExitCode::from(2);
        }
    };

    // --show: показать potfile и выйти.
    if cfg.show {
        return show_potfile(&cfg);
    }

    // --self-test: проверить хеш-функции.
    if cfg.self_test {
        match hash::self_test() {
            Ok(()) => {
                println!("self-test пройден: MD5, SHA1, SHA256, SHA512 — ок");
                ExitCode::SUCCESS
            }
            Err(e) => {
                eprintln!("self-test не пройден: {}", e);
                ExitCode::FAILURE
            }
        }
    } else if let Err(e) = cli::validate(&cfg) {
        eprintln!("ошибка: {}", e);
        eprintln!("используйте --help для справки");
        ExitCode::from(2)
    } else {
        match engine::run(&cfg) {
            Ok(_found) => ExitCode::SUCCESS,
            Err(e) => {
                eprintln!("ошибка: {}", e);
                ExitCode::FAILURE
            }
        }
    }
}

fn show_potfile(cfg: &cli::Config) -> ExitCode {
    match potfile::read_potfile(&cfg.outfile) {
        Ok(entries) => {
            if entries.is_empty() {
                println!("potfile {} пуст", cfg.outfile.display());
            } else {
                for e in &entries {
                    println!("{}:{}", e.hash_hex, e.plain);
                }
            }
            ExitCode::SUCCESS
        }
        Err(e) => {
            eprintln!("ошибка: {}", e);
            ExitCode::FAILURE
        }
    }
}

