//! Чарсеты и маски в стиле hashcat.
//!
//! Токены маски:
//!   ?l — abcdefghijklmnopqrstuvwxyz
//!   ?u — ABCDEFGHIJKLMNOPQRSTUVWXYZ
//!   ?d — 0123456789
//!   ?s — спецсимволы ASCII (пробел, пунктуация)
//!   ?a — ?l?u?d?s
//!   ?h — 0123456789abcdef
//!   ?H — 0123456789ABCDEF
//!   ?b — все байты 0x00..=0xFF
//!
//! Кастомные чарсеты (-1..-4) задаются той же нотацией, например `-1 ?d?l`
//! или буквально `-1 abc`. Литеральные символы в маске означают сами себя.

pub const CHARSET_LOWER: &[u8] = b"abcdefghijklmnopqrstuvwxyz";
pub const CHARSET_UPPER: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZ";
pub const CHARSET_DIGITS: &[u8] = b"0123456789";
pub const CHARSET_SPECIAL: &[u8] = b" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~";
pub const CHARSET_HEX_LOWER: &[u8] = b"0123456789abcdef";
pub const CHARSET_HEX_UPPER: &[u8] = b"0123456789ABCDEF";

/// Все 256 байтов. Для ?b.
pub fn charset_all_bytes() -> Vec<u8> {
    (0u16..=255u16).map(|b| b as u8).collect()
}

/// Разобрать строку чарсета: токены `?x` + литеральные символы.
/// Ошибка на неизвестном токене.
pub fn parse_charset(input: &str) -> Result<Vec<u8>, String> {
    let mut out: Vec<u8> = Vec::new();
    let bytes: Vec<char> = input.chars().collect();
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        if c == '?' && i + 1 < bytes.len() {
            match bytes[i + 1] {
                'l' => out.extend_from_slice(CHARSET_LOWER),
                'u' => out.extend_from_slice(CHARSET_UPPER),
                'd' => out.extend_from_slice(CHARSET_DIGITS),
                's' => out.extend_from_slice(CHARSET_SPECIAL),
                'a' => {
                    out.extend_from_slice(CHARSET_LOWER);
                    out.extend_from_slice(CHARSET_UPPER);
                    out.extend_from_slice(CHARSET_DIGITS);
                    out.extend_from_slice(CHARSET_SPECIAL);
                }
                'h' => out.extend_from_slice(CHARSET_HEX_LOWER),
                'H' => out.extend_from_slice(CHARSET_HEX_UPPER),
                'b' => out.extend_from_slice(&charset_all_bytes()),
                other => {
                    return Err(format!(
                        "неизвестный токен чарсета '?{}' (допустимо: ?l ?u ?d ?s ?a ?h ?H ?b)",
                        other
                    ))
                }
            }
            i += 2;
        } else {
            // Литеральный символ — только ASCII; не-ASCII отдаём как UTF-8 байты.
            let mut buf = [0u8; 4];
            out.extend_from_slice(c.encode_utf8(&mut buf).as_bytes());
            i += 1;
        }
    }
    // Убрать дубликаты, сохранив порядок (как hashcat).
    let mut seen = std::collections::HashSet::new();
    out.retain(|b| seen.insert(*b));
    Ok(out)
}

/// Маска = список чарсетов по позициям.
/// `?d?d?d` → [digits, digits, digits], `pa?s?w?d?d` → литералы + токены.
pub fn parse_mask(input: &str, customs: &[Option<Vec<u8>>; 4]) -> Result<Vec<Vec<u8>>, String> {
    let mut positions: Vec<Vec<u8>> = Vec::new();
    let chars: Vec<char> = input.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '?' && i + 1 < chars.len() {
            let tok = chars[i + 1];
            let set: Vec<u8> = match tok {
                '1'..='4' => {
                    let idx = tok.to_digit(10).unwrap() as usize - 1;
                    customs[idx]
                        .clone()
                        .ok_or_else(|| format!("кастомный чарсет -{} не задан, а используется в маске", idx + 1))?
                }
                'l' => CHARSET_LOWER.to_vec(),
                'u' => CHARSET_UPPER.to_vec(),
                'd' => CHARSET_DIGITS.to_vec(),
                's' => CHARSET_SPECIAL.to_vec(),
                'a' => {
                    let mut v = CHARSET_LOWER.to_vec();
                    v.extend_from_slice(CHARSET_UPPER);
                    v.extend_from_slice(CHARSET_DIGITS);
                    v.extend_from_slice(CHARSET_SPECIAL);
                    v
                }
                'h' => CHARSET_HEX_LOWER.to_vec(),
                'H' => CHARSET_HEX_UPPER.to_vec(),
                'b' => charset_all_bytes(),
                other => {
                    return Err(format!(
                        "неизвестный токен маски '?{}' (допустимо: ?l ?u ?d ?s ?a ?h ?H ?b ?1..?4)",
                        other
                    ))
                }
            };
            if set.is_empty() {
                return Err(format!("пустой чарсет на позиции {} маски", positions.len() + 1));
            }
            positions.push(set);
            i += 2;
        } else {
            // Литеральный символ — позиция из его UTF-8 байтов (ASCII → 1 байт).
            let mut buf = [0u8; 4];
            positions.push(c.encode_utf8(&mut buf).as_bytes().to_vec());
            i += 1;
        }
    }
    Ok(positions)
}

/// Общее число комбинаций маски (u128 — пространства ?a?x? могут быть гигантскими).
pub fn total_combos(positions: &[Vec<u8>]) -> u128 {
    positions
        .iter()
        .fold(1u128, |acc, p| acc.saturating_mul(p.len() as u128))
}

/// Сгенерировать комбинацию по индексу (little-endian по позициям).
/// Индекс разлагается по длинам чарсетов; старшая позиция — старший разряд.
pub fn combo_from_index(positions: &[Vec<u8>], mut idx: u128) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::with_capacity(positions.len());
    for pos in positions.iter().rev() {
        let len = pos.len() as u128;
        out.push(pos[(idx % len) as usize]);
        idx /= len;
    }
    out.reverse();
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_charset_tokens() {
        assert_eq!(parse_charset("?d").unwrap(), b"0123456789");
        assert_eq!(parse_charset("?l?u").unwrap().len(), 26 + 26);
        assert!(parse_charset("?x").is_err());
    }

    #[test]
    fn parse_charset_literal_plus_tokens() {
        let cs = parse_charset("ab?d").unwrap();
        assert!(cs.contains(&b'a') && cs.contains(&b'b') && cs.contains(&b'0'));
    }

    #[test]
    fn parse_charset_deduplicates() {
        let cs = parse_charset("?d?d").unwrap();
        assert_eq!(cs.len(), 10);
    }

    #[test]
    fn parse_mask_literals_and_tokens() {
        let mask = parse_mask("pa?sw?d", &[None, None, None, None]).unwrap();
        assert_eq!(mask.len(), 5);
        assert_eq!(mask[0], vec![b'p']);
        assert_eq!(mask[1], vec![b'a']);
        assert_eq!(mask[2], CHARSET_SPECIAL);
        assert_eq!(mask[3], vec![b'w']);
        assert_eq!(mask[4], CHARSET_DIGITS);
    }

    #[test]
    fn parse_mask_custom_charset() {
        let customs = [Some(b"ab".to_vec()), None, None, None];
        let mask = parse_mask("?1?1?1", &customs).unwrap();
        assert_eq!(mask, vec![b"ab".to_vec(), b"ab".to_vec(), b"ab".to_vec()]);
    }

    #[test]
    fn parse_mask_missing_custom_fails() {
        assert!(parse_mask("?1", &[None, None, None, None]).is_err());
    }

    #[test]
    fn parse_mask_unknown_token_fails() {
        assert!(parse_mask("?z", &[None, None, None, None]).is_err());
    }

    #[test]
    fn combo_index_roundtrip() {
        let mask = parse_mask("?d?d?d", &[None, None, None, None]).unwrap();
        assert_eq!(total_combos(&mask), 1000);
        assert_eq!(combo_from_index(&mask, 0), b"000");
        assert_eq!(combo_from_index(&mask, 42), b"042");
        assert_eq!(combo_from_index(&mask, 999), b"999");
    }

    #[test]
    fn combo_index_mixed() {
        let mask = parse_mask("?l?d", &[None, None, None, None]).unwrap();
        assert_eq!(combo_from_index(&mask, 0), b"a0");
        // idx = i_lower * 10 + i_digit: 'b' (индекс 1) + '5' → 15
        assert_eq!(combo_from_index(&mask, 15), b"b5");
        assert_eq!(total_combos(&mask), 260);
    }

    #[test]
    fn total_combos_saturates() {
        // 26^28 ≈ 4.2e39 > u128::MAX ≈ 3.4e38 — сатурируется
        let mask: Vec<Vec<u8>> = (0..28).map(|_| CHARSET_LOWER.to_vec()).collect();
        assert_eq!(total_combos(&mask), u128::MAX);
    }
}

