//! Генераторы кандидатов для режимов атаки.
//!
//! Все итераторы потокобезопасны: каждый воркер получает диапазон индексов
//! [start, end) и генерирует кандидатов независимо — без разделяемого состояния.
//! Это даёт идеальную балансировку нагрузки.

use crate::charset::total_combos;

/// Режим brute-force: маска фиксированной длины.
/// `total = total_combos(mask)`, кандидат по индексу `idx` (см. combo_from_index).
pub fn brute_total(mask: &[Vec<u8>]) -> u128 {
    total_combos(mask)
}

/// Режим straight: словарь прочитан в память, кандидат = строка с индексом `idx`.
pub fn straight_total(words: &[Vec<u8>]) -> u128 {
    words.len() as u128
}

pub fn straight_candidate<'a>(words: &'a [Vec<u8>], idx: u128) -> &'a [u8] {
    &words[idx as usize]
}

/// Режим combinator: пары (i, j), где i из первого словаря, j из второго.
/// Индекс разворачивается как idx = i * w2.len() + j.
pub fn combinator_total(w1: &[Vec<u8>], w2: &[Vec<u8>]) -> u128 {
    (w1.len() as u128).saturating_mul(w2.len() as u128)
}

pub fn combinator_candidate(w1: &[Vec<u8>], w2: &[Vec<u8>], idx: u128) -> Vec<u8> {
    let j = idx % w2.len() as u128;
    let i = idx / w2.len() as u128;
    let mut out = Vec::with_capacity(w1[i as usize].len() + w2[j as usize].len());
    out.extend_from_slice(&w1[i as usize]);
    out.extend_from_slice(&w2[j as usize]);
    out
}

/// Развернуть маску в раунды инкремента: подмаски длин [increment_min..=increment_max],
/// обрезанные по фактической длине маски. Если инкремент выключен — один раунд.
pub fn mask_rounds(
    positions: &[Vec<u8>],
    increment_min: usize,
    increment_max: usize,
) -> Vec<Vec<Vec<u8>>> {
    let lo = increment_min.clamp(1, positions.len());
    let hi = increment_max.clamp(1, positions.len());
    if lo > hi {
        return vec![positions.to_vec()];
    }
    (lo..=hi).map(|l| positions[..l].to_vec()).collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::charset::combo_from_index;

    fn mask_digits(len: usize) -> Vec<Vec<u8>> {
        vec![b"0123456789".to_vec(); len]
    }

    #[test]
    fn brute_generates_sequence() {
        let mask = mask_digits(2);
        assert_eq!(brute_total(&mask), 100);
        assert_eq!(combo_from_index(&mask, 0), b"00");
        assert_eq!(combo_from_index(&mask, 17), b"17");
        assert_eq!(combo_from_index(&mask, 99), b"99");
    }

    #[test]
    fn straight_indexes_words() {
        let words: Vec<Vec<u8>> = vec![b"one".to_vec(), b"two".to_vec(), b"three".to_vec()];
        assert_eq!(straight_total(&words), 3);
        assert_eq!(straight_candidate(&words, 0), b"one");
        assert_eq!(straight_candidate(&words, 2), b"three");
    }

    #[test]
    fn combinator_enumerates_pairs() {
        let w1: Vec<Vec<u8>> = vec![b"a".to_vec(), b"b".to_vec()];
        let w2: Vec<Vec<u8>> = vec![b"1".to_vec(), b"2".to_vec(), b"3".to_vec()];
        assert_eq!(combinator_total(&w1, &w2), 6);
        assert_eq!(combinator_candidate(&w1, &w2, 0), b"a1");
        assert_eq!(combinator_candidate(&w1, &w2, 2), b"a3");
        assert_eq!(combinator_candidate(&w1, &w2, 3), b"b1");
        assert_eq!(combinator_candidate(&w1, &w2, 5), b"b3");
    }

    #[test]
    fn combinator_total_big() {
        let big: Vec<Vec<u8>> = (0..50_000).map(|i| vec![i as u8]).collect();
