        // 50_000² влезает в u128 — проверяем точное значение, а не сатурацию
        assert_eq!(combinator_total(&big, &big2), 2_500_000_000u128);
    }

    #[test]
    fn mask_rounds_full_range() {
        let m = mask_digits(4);
        let rounds = mask_rounds(&m, 1, 4);
        assert_eq!(rounds.len(), 4); // длины 1,2,3,4
        assert_eq!(rounds[0].len(), 1);
        assert_eq!(rounds[1].len(), 2);
        assert_eq!(rounds[2].len(), 3);
        assert_eq!(rounds[3].len(), 4);
    }

    #[test]
    fn mask_rounds_increment_slices() {
        let m = mask_digits(4);
        let rounds = mask_rounds(&m, 2, 4);
        assert_eq!(rounds.len(), 3); // длины 2,3,4
        assert_eq!(rounds[0].len(), 2);
        assert_eq!(rounds[1].len(), 3);
        assert_eq!(rounds[2].len(), 4);
    }

    #[test]
    fn mask_rounds_clamps_bounds() {
        let m = mask_digits(3);
        // min больше длины маски → только полная длина
        let rounds = mask_rounds(&m, 5, 9);
        assert_eq!(rounds.len(), 1);
        assert_eq!(rounds[0].len(), 3);
        // max меньше min после клампа → полная маска
        let rounds2 = mask_rounds(&m, 3, 1);
        assert_eq!(rounds2.len(), 1);
        assert_eq!(rounds2[0].len(), 3);
    }
